#include <Arduino.h>
#include <stdlib.h>

const uint8_t TRIG = 3;
const uint8_t ECHO = 2;
char input[24];
uint8_t used = 0;
unsigned long lastByte = 0;
unsigned long lastSample = 0;
long measured = 0;
bool valid = false;

void sampleDistance() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long duration = pulseIn(ECHO, HIGH, 40000UL);
  valid = duration != 0;
  if (valid) measured = duration / 58UL;
  lastSample = millis();
}

void compareInput() {
  if (!used) return;
  input[used] = '\0';
  char *end;
  long target = strtol(input, &end, 10);
  used = 0;
  if (end == input) return;
  sampleDistance();
  if (valid) {
    if (measured > target) Serial.println("Measured distance is greater");
    else if (measured < target) Serial.println("Measured distance is less");
    else Serial.println("Measured distance is equal to the target");
  }
  Serial.println("Enter a distance in cm to compare: ");
}

void setup() {
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  digitalWrite(TRIG, LOW);
  Serial.begin(9600);
  Serial.println("Enter a distance in cm to compare: ");
}

void loop() {
  while (Serial.available()) {
    char c = (char)Serial.read();
    lastByte = millis();
    if (c == '\n' || c == '\r') compareInput();
    else if (used < sizeof(input) - 1) input[used++] = c;
  }
  if (used && millis() - lastByte >= 20UL) compareInput();
  if (millis() - lastSample >= 60UL) sampleDistance();
}
